def setup(bot):
    for name in PLANNED:
        if bot.get_command(name):
            continue
        async def scaffold(ctx, *, arguments=""):
            await ctx.reply(
                f"`!{ctx.invoked_with}` is registered in Hikaru's command roadmap, "
                "but its full workflow is not implemented in this starter yet. "
                "Use `!help` for working commands.",
                mention_author=False
            )
        bot.add_command(commands.Command(scaffold, name=name, help="Planned feature scaffold"))
